import type { NavItem, NavSection } from '@linm-soft-org/linm-web-common-components';

function normalizeNavPath(path: string): string {
  if (!path) return '/';
  if (path === '/') return '/';
  return path.endsWith('/') ? path.slice(0, -1) : path;
}

function collectLeaves(items: NavItem[], out: NavItem[]): void {
  for (const item of items) {
    const children = (item as NavItem & { children?: NavItem[] }).children;
    if (children?.length) {
      collectLeaves(children, out);
      continue;
    }
    if (item.path && item.path !== '#') out.push(item);
  }
}

/** Standalone mock nav — same longest-prefix rule as shell NavRoot. */
export function resolveNavTitleFromSections(pathname: string, sections: NavSection[]): string {
  const path = normalizeNavPath(pathname);
  const leaves: NavItem[] = [];
  for (const section of sections) {
    collectLeaves(section.items, leaves);
  }

  let best: { path: string; label: string } | null = null;
  for (const item of leaves) {
    const itemPath = normalizeNavPath(item.path);
    if (path === itemPath || path.startsWith(`${itemPath}/`)) {
      if (!best || itemPath.length > best.path.length) {
        best = { path: itemPath, label: item.label };
      }
    }
  }

  return best?.label ?? '';
}
